// ===== SETTINGS: the only node you normally need to edit =====
return [{
  json: {
    SHEET_URL: 'PASTE_YOUR_GOOGLE_SHEET_URL_HERE',
    TIMEZONE: 'America/Chicago',  // the agency's time zone
    COOLDOWN_DAYS: 30,            // never re-contact anyone reached in the last 30 days
    MAX_TO_SCORE: 12,             // how many candidates the AI reviews per job
    MIN_SCORE: 70,                // 70+ = strong match
    // Candidates with these statuses are never contacted
    EXCLUDED_STATUSES: ['do not contact', 'placed', 'not looking', 'interviewing', 'responded', 'email bounced'],
  },
}];

// Pre-filter: skip people who must not be contacted, skip recent contacts,
// and keep only candidates whose title/skills overlap the job.
const S = $('Settings').first().json;
const form = $('Job Opening Form').first().json;
const job = {
  agency: form['Agency name'] || 'our agency',
  title: form['Job title'],
  skills: form['Required skills'],
  location: form['Location'],
  pay: form['Pay rate'] || 'Not specified',
  shift: form['Shift / schedule'] || 'Not specified',
  client: form['Client description'] || 'one of our clients',
  recruiter_name: form['Recruiter name'],
  recruiter_email: form['Recruiter email'],
  max_contacts: Number(form['Max candidates to contact']) || 5,
};

const excluded = S.EXCLUDED_STATUSES.map((s) => s.toLowerCase());
const STOP = new Set(['and', 'or', 'the', 'with', 'for', 'of', 'in', 'to', 'a', 'an', 'on', 'at']);
const words = (s) => String(s || '').toLowerCase().split(/[^a-z0-9+#]+/).filter((w) => w.length > 1 && !STOP.has(w));
const jobTerms = new Set(words(`${job.title} ${job.skills}`));
const now = new Date();

const shortlist = [];
for (const item of $input.all()) {
  const c = item.json;
  if (!c.candidate_id) continue;
  if (excluded.includes(String(c.status || '').trim().toLowerCase())) continue;
  if (c.last_contacted) {
    const last = new Date(c.last_contacted);
    if (!isNaN(last) && (now - last) / 86400000 < S.COOLDOWN_DAYS) continue;
  }
  const candTerms = new Set(words(`${c.current_title} ${c.skills}`));
  let overlap = 0;
  for (const t of jobTerms) if (candTerms.has(t)) overlap++;
  if (overlap === 0) continue;
  shortlist.push({ json: { ...c, pre_score: overlap, job } });
}

shortlist.sort((a, b) => b.json.pre_score - a.json.pre_score);
return shortlist.slice(0, S.MAX_TO_SCORE);

parameters.text:
=You are helping a recruiter at a staffing agency decide which past candidates to re-engage for a new job opening.

JOB
Title: {{ $json.job.title }}
Required skills: {{ $json.job.skills }}
Location: {{ $json.job.location }}
Pay: {{ $json.job.pay }}
Shift / schedule: {{ $json.job.shift }}

CANDIDATE
Current title: {{ $json.current_title }}
Skills and certifications: {{ $json.skills }}
Years of experience: {{ $json.years_experience }}
Location: {{ $json.location }}
Desired pay: {{ $json.desired_pay }}
Recruiter notes: {{ $json.notes || 'None' }}

Score how well this candidate fits the job from 0 to 100. Use only job-relevant factors: skills and certifications, relevant experience, location or commute, pay expectations, and preferences stated in the recruiter notes. Do not consider or guess at age, gender, race, ethnicity, religion, disability, or any other protected characteristic.

Scoring guide: 85-100 strong fit, 70-84 good fit worth contacting, 50-69 partial fit, below 50 not a fit.

Reply with JSON only, no other text:
{"score": <number 0-100>, "reason": "<one or two sentences the recruiter can verify>"}

