// Read the AI's JSON reply for each candidate and attach score + reason.
const MIN_SCORE = $('Settings').first().json.MIN_SCORE;
const candidates = $('Pre-filter Candidates').all();

return $input.all().map((item, i) => {
  const c = candidates[i].json;
  let score = 0;
  let reason = 'AI response could not be read; review manually.';
  const match = String(item.json.text || '').match(/\{[\s\S]*\}/);
  if (match) {
    try {
      const parsed = JSON.parse(match[0]);
      score = Math.max(0, Math.min(100, Math.round(Number(parsed.score) || 0)));
      reason = String(parsed.reason || reason).trim();
    } catch (e) { /* keep defaults */ }
  }
  return { json: { ...c, score, reason, matched: score >= MIN_SCORE } };
});

// One log row per scored candidate, matching the Match_Log column headers.
const S = $('Settings').first().json;
const runDate = new Intl.DateTimeFormat('sv-SE', { timeZone: S.TIMEZONE, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }).format(new Date());
return $input.all().map((i) => ({
  json: {
    run_date: runDate,
    job_title: i.json.job.title,
    candidate_id: i.json.candidate_id,
    candidate_name: `${i.json.first_name} ${i.json.last_name}`,
    score: i.json.score,
    matched: i.json.matched ? 'Yes' : 'No',
    reason: i.json.reason,
  },
}));

// Keep only strong matches, best first, up to the limit set in the form.
const matches = $input.all()
  .filter((i) => i.json.matched)
  .sort((a, b) => b.json.score - a.json.score);
if (matches.length === 0) return [];
return matches.slice(0, matches[0].json.job.max_contacts);

parameters.text:
=Write a short re-engagement email from a recruiter to a past candidate about a new job opening.

Recruiter: {{ $json.job.recruiter_name }} at {{ $json.job.agency }}
Candidate first name: {{ $json.first_name }}
Candidate background: {{ $json.current_title }}; skills: {{ $json.skills }}; notes: {{ $json.notes || 'none' }}

Job: {{ $json.job.title }} with {{ $json.job.client }}
Location: {{ $json.job.location }}
Pay: {{ $json.job.pay }}
Shift / schedule: {{ $json.job.shift }}
Why it may fit them: {{ $json.reason }}

Rules:
- 90 to 140 words, warm and professional, plain text.
- Mention one or two specific reasons the role fits their background.
- Only use facts given above. Do not invent benefits, bonuses, start dates or other details.
- Do not mention AI, scores, or that they were matched by software.
- End by asking whether they would like details or a quick call this week.
- Sign off with the recruiter's first name and the agency name.

Reply with JSON only, no other text:
{"subject": "<subject line under 8 words>", "body": "<email body, use \n for line breaks>"}

